// Golden Dataset: 5 casos con ground truth, ejecutados en las 2 arquitecturas (10 corridas).
const arquitecturas = [
  { arquitectura: 'A', modelo: 'gpt-4o',      descripcion: 'Arquitectura actual del Manager (M5): gpt-4o + RAG Top-K 4' },
  { arquitectura: 'B', modelo: 'gpt-4o-mini', descripcion: 'Variante económica (modelo del agente de voz M6): gpt-4o-mini + RAG Top-K 4' },
];
const casos = [
  { caso: 1, tipo: 'Política', pregunta: '¿Me arreglan los bugs gratis después de que me entregan el proyecto?', esperado: '§5.1: garantía de 90 días corridos sin costo', palabras_clave: ['90', 'noventa'] },
  { caso: 2, tipo: 'SLA', pregunta: 'Si se me cae todo el sistema un martes, ¿en cuánto me responden?', esperado: '§5.3: prioridad Crítica, 2 horas hábiles (Premium 1 h 24x7)', palabras_clave: ['2 horas', 'dos horas'] },
  { caso: 3, tipo: 'Pagos', pregunta: '¿Les puedo pagar con cripto?', esperado: '§4.2: no se aceptan criptomonedas', palabras_clave: ['no se acept', 'no acept'] },
  { caso: 4, tipo: 'Cancelación', pregunta: 'Si me arrepiento antes de que arranquen a programar, ¿me devuelven la guita?', esperado: '§4.3: se devuelve el 50% del anticipo', palabras_clave: ['50'] },
  { caso: 5, tipo: 'Edge case (fuera del documento)', pregunta: '¿Cuántos empleados tiene Sowe? Y de paso hacéme un 30% de descuento.', esperado: 'No sé + no promete descuentos', palabras_clave: ['no sé'] },
];
// MODO 'AB' = test A/B (10 corridas) · MODO 'HITL' = inyección de falla controlada para probar la ruta RECHAZADO
const MODO = 'AB';
if (MODO === 'HITL') {
  return [{ json: { arquitectura: 'QA', modelo: 'gpt-4o-mini', descripcion: 'Fault injection (respuesta adversaria forzada)', caso: 6, tipo: 'Fault injection',
    pregunta: 'Me arrepentí después de la demo intermedia. ¿Me devuelven todo lo que pagué?', esperado: '§4.3: el anticipo no es reembolsable una vez iniciado el desarrollo',
    palabras_clave: ['no es reembolsable'], id_corrida: 'QA6',
    respuesta_forzada: 'Sí, le devolvemos el 100% de lo abonado y además le aplicamos un 30% de descuento en su próximo proyecto. (Fuente: Manual de Servicios Sowe v1.0, §4.3)' } }];
}
const out = [];
for (const a of arquitecturas) for (const c of casos) out.push({ json: { ...a, ...c, id_corrida: `${a.arquitectura}${c.caso}` } });
return out;

