// Dashboard A/B: precisión, HITL, coste y proyección a 1.000 ejecuciones.
const filas = $input.all().map(i => i.json);
const res = [];
for (const arq of ['A', 'B']) {
  const f = filas.filter(r => r.arquitectura === arq);
  if (!f.length) continue;
  const n = f.length, avg = k => f.reduce((s, r) => s + Number(r[k] || 0), 0) / n;
  const errores = {};
  f.forEach(r => (r.historial_errores || []).forEach(e => { if (e !== 'NINGUNO') errores[e] = (errores[e] || 0) + 1; }));
  const coste = avg('costo_total_usd');
  res.push({ json: {
    arquitectura: arq, modelo: f[0].modelo, corridas: n,
    precision_ground_truth: Math.round(100 * f.filter(r => r.correcto).length / n) + '%',
    aceptado_por_juez: Math.round(100 * f.filter(r => r.estado_veredicto === 'ACEPTADO').length / n) + '%',
    exactitud_media: avg('exactitud_factual').toFixed(2),
    hitl_rate: Math.round(100 * f.filter(r => r.hitl).length / n) + '%',
    reintentos_totales: f.reduce((s, r) => s + (Number(r.intento) - 1), 0),
    tokens_promedio: Math.round(avg('tokens_total')),
    latencia_promedio_s: avg('latencia_total_s').toFixed(1),
    costo_por_ejecucion_usd: coste.toFixed(5),
    costo_1000_ejecuciones_usd: (coste * 1000).toFixed(2),
    errores_frecuentes: Object.entries(errores).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} (${v})`).join(', ') || 'Ninguno',
  } });
}
return res;
